6	// ─── Big-endian read helpers ─────────────────────────────────────────────────
7	
8	static inline uint16_t be16(const uint8_t* p) {
9	    return static_cast<uint16_t>(p[0] << 8 | p[1]);
10	}
11	static inline uint32_t be32(const uint8_t* p) {
12	    return (static_cast<uint32_t>(p[0]) << 24 |
13	            static_cast<uint32_t>(p[1]) << 16 |
14	            static_cast<uint32_t>(p[2]) <<  8 |
15	            static_cast<uint32_t>(p[3]));
16	}
17	static inline uint64_t be64(const uint8_t* p) {
18	    return (static_cast<uint64_t>(be32(p)) << 32 |
19	            static_cast<uint64_t>(be32(p + 4)));
20	}
