22	// ─── ITCH 5.0 message sizes (bytes, excluding the 2-byte length prefix) ─────
23	// Sizes from Nasdaq TotalView-ITCH 5.0 specification §4.
24	// Only the types we care about are listed; everything else falls through to
25	// the skip branch which reads the declared length from the frame header.
26	
27	static constexpr uint16_t SIZE_ADD_ORDER          = 36;
28	static constexpr uint16_t SIZE_ADD_ORDER_MPID     = 40;
29	static constexpr uint16_t SIZE_EXECUTE_ORDER      = 31;
30	static constexpr uint16_t SIZE_EXECUTE_ORDER_PRICE= 36;
31	static constexpr uint16_t SIZE_CANCEL_ORDER       = 23;
32	static constexpr uint16_t SIZE_DELETE_ORDER       = 19;
33	static constexpr uint16_t SIZE_REPLACE_ORDER      = 35;
34	
35	// Field offsets within each message body (after the 1-byte type field).
36	// Timestamp (6 bytes) follows the type at offset 1; fields begin at offset 7
37	// for most types.
38	
39	// Add Order (type 'A', 36 bytes)
40	//   [0]  type 1B
41	//   [1]  stock locate 2B
42	//   [3]  tracking number 2B
43	//   [5]  timestamp 6B
44	//   [11] order ref 8B
45	//   [19] side 1B
46	//   [20] shares 4B
47	//   [24] stock 8B
48	//   [32] price 4B
49	static constexpr int OFF_A_REF    = 11;
50	static constexpr int OFF_A_SIDE   = 19;
51	static constexpr int OFF_A_SHARES = 20;
52	static constexpr int OFF_A_PRICE  = 32;
53	
54	// Execute Order (type 'E', 31 bytes)
55	//   [0]  type 1B, [1] stock locate 2B, [3] tracking 2B, [5] ts 6B
56	//   [11] order ref 8B
57	//   [19] executed shares 4B
58	//   [23] match number 8B
59	static constexpr int OFF_E_REF    = 11;
60	static constexpr int OFF_E_SHARES = 19;
61	
62	// Delete Order (type 'D', 19 bytes)
63	//   [11] order ref 8B
64	static constexpr int OFF_D_REF = 11;
65	
66	// Replace Order (type 'U', 35 bytes)
67	//   [11] original order ref 8B
68	//   [19] new order ref 8B
69	//   [27] shares 4B
70	//   [31] price 4B
71	static constexpr int OFF_U_OLD_REF = 11;
72	static constexpr int OFF_U_NEW_REF = 19;
73	static constexpr int OFF_U_SHARES  = 27;
74	static constexpr int OFF_U_PRICE   = 31;
