76	// ─── Parser implementation ───────────────────────────────────────────────────
77	
78	ParseStats parse_buffer(
79	        const uint8_t* buf,
80	        std::size_t    len,
81	        MessageVisitor visitor) {
82	
83	    ParseStats stats;
84	    std::size_t pos = 0;
85	
86	    while (pos + 2 <= len) {
87	        const uint16_t msg_len = be16(buf + pos);
88	        pos += 2;
89	
90	        if (msg_len == 0) {
91	            // Padding / heartbeat frame — skip without error.
92	            continue;
93	        }
94	        if (pos + msg_len > len) {
95	            // Truncated message at end of buffer — stop cleanly.
96	            ++stats.error_count;
97	            break;
98	        }
99	
100	        const uint8_t* msg = buf + pos;
101	        const MsgType  typ = static_cast<MsgType>(msg[0]);
102	
103	        switch (typ) {
104	        case MsgType::AddOrder:
105	        case MsgType::AddOrderMPID: {
106	            if (msg_len < SIZE_ADD_ORDER) { ++stats.error_count; break; }
107	            AddOrder a;
108	            a.order_ref = be64(msg + OFF_A_REF);
109	            a.side      = static_cast<char>(msg[OFF_A_SIDE]);
110	            a.shares    = be32(msg + OFF_A_SHARES);
111	            a.price     = be32(msg + OFF_A_PRICE);
112	            ++stats.add_count;
113	            if (visitor.on_add) visitor.on_add(a);
114	            break;
